Here is a Python function that implements the Miller-Rabin primality test algorithm to check if a number is prime:

```python
import random

def is_prime(n, num_trials=5):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False

    # Reduce n to an odd number greater than 3
    d = n - 1
    while d % 2 == 0:
        d //= 2

    for _ in range(num_trials):
        a = random.randint(2, n - 1)
        x = pow(a, d, n)

        if x == 1 or x == n - 1:
            continue

        for _ in range(d - 1):
            x = pow(x, 2, n)
            if x == n - 1:
                break
        else:
            return False # Not a prime number

    return True
```

