def count_prime_factors(n):
    prime_factors = []
    max_factor = math.floor(math.sqrt(n))
    for i in range(2, max_factor + 1):
        while n % i == 0:
            n //= i
            prime_factors.append(i)
        if n == 1:
            break
    if n > 1:
        prime_factors.append(n)
    return len(prime_factors)

